class Event:
    __slots__ = ("_source", "_external_id", "body", "received_at")

    def __init__(self, source, external_id, body, received_at):
        self._source = source
        self._external_id = external_id
        self.body = body                  # mutable payload, not hashed
        self.received_at = received_at

    @property
    def source(self):
        return self._source               # read-only: identity cannot drift

    @property
    def external_id(self):
        return self._external_id

    def __eq__(self, other):
        if not isinstance(other, Event):
            return NotImplemented         # let the other side answer; never raise
        return (self._source, self._external_id) == (other._source, other._external_id)

    def __hash__(self):
        return hash((self._source, self._external_id))  # same fields as __eq__

    def __repr__(self):
        return f"Event(source={self._source!r}, external_id={self._external_id!r})"

Key decisions: equality and hash use the identical identity tuple, so the contract holds; identity is behind read-only properties so no caller can mutate a hashed field after the event enters a set; body/received_at stay freely mutable because they never participate in hashing; NotImplemented keeps Event == ForeignWrapper symmetric and future-proof; repr identifies without leaking payload to logs.

