# Ключевые решения дизайна — идентичность за read-only property, хеш по тем же полям
class Event:
    __slots__ = ("_source", "_external_id", "body", "received_at")

    def __init__(self, source, external_id, body, received_at):
        self._source = source
        self._external_id = external_id
        self.body = body                  # изменяемая нагрузка, не хешируется
        self.received_at = received_at

    @property
    def source(self):
        return self._source               # read-only: идентичность не уплывёт

    @property
    def external_id(self):
        return self._external_id

    def __eq__(self, other):
        if not isinstance(other, Event):
            return NotImplemented         # дать слово второй стороне; никогда не поднимать
        return (self._source, self._external_id) == (other._source, other._external_id)

    def __hash__(self):
        return hash((self._source, self._external_id))  # те же поля, что в __eq__

    def __repr__(self):
        return f"Event(source={self._source!r}, external_id={self._external_id!r})"

Решения: равенство и хеш используют один и тот же кортеж идентичности — контракт соблюдён; идентичность за read-only property, так что никто не изменит хешированное поле после попадания события в set; body/received_at свободно изменяемы, потому что в хешировании не участвуют; NotImplemented сохраняет симметрию Event == ForeignWrapper и совместимость с будущими типами; repr идентифицирует событие, не сливая payload в логи.
